import type { QueueState, TaskNotification, TaskNotificationSettings, WebUITask } from "./types";
import type { WebUIBridge } from "./legacy-bridge";
import type { Locale } from "./i18n/types";

export interface WebUIState {
  [key: string]: any;
  tasks: WebUITask[];
  referenceFiles: any[];
  selectedTaskId: string | null;
  queue: QueueState;
  queueRenderKey: string | null;
  queueRequestSeq: number;
  queueDispatchSyncTimerId: number | null;
  tasksRequestSeq: number;
  realtimeSource: EventSource | null;
  realtimeSnapshotNeedsArchiveMigration: boolean;
  queueDragTaskId: string | null;
  activeTaskGroupCollapsed: boolean;
  expandedTaskGroupKey: string | null;
  taskNotifications: TaskNotification[];
  taskNotificationUnreadCount: number;
  taskNotificationCenterOpen: boolean;
  taskNotificationToastTimerIds: number[];
  taskNotificationSettings: TaskNotificationSettings;
  taskNotificationSeenKeys: Set<string>;
  batchMode?: boolean;
  batchSelectedTaskIds: string[];
  suppressTaskClickAfterDrag?: boolean;
  tasksRenderKey?: number | string | null;
  expandedTaskGroupAnimationPending?: boolean;
  taskSearchHistoryResultQuery?: string;
  taskSearchHistoryResultIds?: string[];
  taskSearchHistoryRequestSeq: number;
  previewRenderKey?: number | string | null;
  previewTask?: WebUITask | null;
  previewOutputUrls?: string[];
  mode?: string;
  images: any[];
  pendingTaskId?: string | null;
  authAvailable?: boolean;
  taskViewedRequestIds: Set<string>;
  legacyArchivedTaskIds: string[];
  batchSelectionAnchorTaskId?: string | null;
  batchSelectionDrag?: any;
  runTimerId?: number | null;
  runStartedAt?: number | null;
  runFeedbackAction?: string | null;
  uiClockTimerId?: number | null;
  promptTemplateQuery?: string;
  promptTemplateCategories?: any[];
  promptTemplateCategory?: string;
  promptTemplates?: any[];
  promptTemplateFilter?: string;
  selectedPromptTemplateId?: string | null;
  quickGalleryFocusItemId?: string | null;
  activeGalleryCategory?: string;
  hoveredGalleryItemId?: string | null;
  recentAssets: any[];
  galleryItems: any[];
  promptSnippets: any[];
  colorPaletteManageMode?: boolean;
  selectedColorCode?: string;
  activeColorChip?: any;
  activeColorRange?: any;
  draggedPromptChip?: any;
  activePromptSnippetRange?: any;
  activePromptSnippetChip?: any;
  promptSnippetSelectionRange?: any;
  promptSnippetSelectionText?: string;
  apiSettings?: any;
  apiSettingsSaveTimerId?: number | null;
  mainModelComboboxOpen?: boolean;
  mainModelOptionIndex: number;
  mainModelShowAllOptions?: boolean;
  customSizeMode?: any;
  customSizeTransitionSeq: number;
  customAspectRatioLocked?: boolean;
  customAspectRatioValue?: any;
  customAspectRatioSource?: string;
  galleryGridTransitionSeq: number;
  galleryGridTransitionTimerId?: any;
  taskInputRestoreSeq?: number;
  sidebarResize?: any;
  themePreference?: string;
  themeSystemQuery?: any;
  colorPalette?: any;
  addToGalleryIndex?: any;
  authStatus?: any;
  pendingAuthSource?: any;
  collectedReferences: any[];
  galleryCategories: any[];
}

export type LegacyBridge = WebUIBridge;

declare global {
  interface Window {
    __codexImageWebUI?: LegacyBridge;
    __codexImageI18n?: {
      applyLocaleToDocument: () => void;
      locale: () => Locale;
      setLocale: (locale: Locale, options?: { persist?: boolean }) => void;
      t: (key: string, locale?: Locale) => string;
    };
    startRealtimeUpdates?: (options?: { migrateLegacyArchives?: boolean }) => boolean;
    closeRealtimeUpdates?: () => void;
    refreshQueue?: () => Promise<boolean>;
    applyQueueState?: (queue: any) => void;
    applyQueueTasks?: (queue: any) => void;
    updateQueueElapsedDisplays?: () => void;
    openLightbox?: (url: string, urls?: string[], index?: number) => void;
    closeLightbox?: () => void;
    showLightboxImage?: (index: number) => void;
    showPreviousLightboxImage?: () => void;
    showNextLightboxImage?: () => void;
    addToInput?: (url: string) => Promise<void>;
    clientDirectDownload?: (url: string, filename: string) => Promise<void>;
  }
}

export function getLegacyBridge(): LegacyBridge {
  const bridge = window.__codexImageWebUI;
  if (!bridge) {
    throw new Error("WebUI legacy bridge is not initialized");
  }
  return bridge;
}

export function getState(): WebUIState {
  return getLegacyBridge().state;
}
